:root {
  --bg: #f4f1de;
  --surface: #ffffff;
  --text: #2d2a32;
  --primary: #3d5a80;
  --primary-hover: #2c4366;
  --accent: #ee6c4d;
  --success: #4caf50;
  --border: #d0ccc0;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.card {
  background: var(--surface);
  border-radius: var(--radius);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
  padding: 2rem;
  width: 100%;
  max-width: 600px;
  margin: 1rem auto;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 0.25rem;
}

h2 {
  font-size: 1.25rem;
  margin-top: 1.5rem;
  margin-bottom: 0.75rem;
}

.subtitle {
  color: #6b6a6e;
  margin-bottom: 1.5rem;
}

.field {
  margin-bottom: 1rem;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

input[type="text"],
input[type="number"] {
  width: 100%;
  padding: 0.6rem 0.75rem;
  font-size: 1rem;
  font-family: inherit;
  border: 2px solid var(--border);
  border-radius: 8px;
  transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(61, 90, 128, 0.25);
}

.btn {
  display: inline-block;
  padding: 0.6rem 1.25rem;
  font-size: 1rem;
  font-family: inherit;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.btn.primary {
  background: var(--primary);
  color: white;
}

.btn.primary:hover {
  background: var(--primary-hover);
}

.btn.primary:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn.primary:active {
  transform: scale(0.98);
}

.btn.small {
  padding: 0.4rem 0.8rem;
  font-size: 0.9rem;
}

.error {
  color: var(--accent);
  font-size: 0.9rem;
  margin-top: 0.5rem;
  min-height: 1.4em;
}

.empty-state {
  color: #6b6a6e;
  font-style: italic;
  padding: 1rem 0;
}

.book-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.book-card {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1rem;
  background: #faf9f6;
}

.book-card.finished {
  border-color: var(--success);
  background: #f0faf0;
}

.book-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
}

.book-title {
  font-size: 1.1rem;
  font-weight: 700;
  word-break: break-word;
}

.badge {
  font-size: 0.8rem;
  font-weight: 700;
  padding: 0.15rem 0.5rem;
  border-radius: 999px;
  background: var(--success);
  color: white;
  white-space: nowrap;
}

.progress-container {
  margin: 0.5rem 0;
}

.progress-bar {
  height: 12px;
  background: #e0e0e0;
  border-radius: 999px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  width: 0%;
  background: var(--primary);
  border-radius: 999px;
  transition: width 0.3s ease;
}

.progress-fill.finished {
  background: var(--success);
}

.progress-text {
  display: flex;
  justify-content: space-between;
  font-size: 0.9rem;
  margin-top: 0.25rem;
  color: #4a4a4a;
}

.log-form {
  display: flex;
  gap: 0.5rem;
  margin-top: 0.75rem;
  flex-wrap: wrap;
  align-items: flex-end;
}

.log-form .field {
  flex: 1 1 120px;
  margin-bottom: 0;
}

.log-form label {
  font-size: 0.85rem;
  font-weight: 500;
}

.log-form input {
  padding: 0.4rem 0.6rem;
  font-size: 0.95rem;
}

.log-form .btn {
  flex: 0 0 auto;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 1.25rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  .log-form .field {
    flex: 1 1 100%;
  }
}

(function () {
  'use strict';

  // State
  let books = [];
  let nextId = 1;

  // DOM references
  const addForm = document.getElementById('add-book-form');
  const titleInput = document.getElementById('book-title');
  const pagesInput = document.getElementById('book-pages');
  const addError = document.getElementById('add-error');
  const bookList = document.getElementById('book-list');
  const emptyState = document.getElementById('empty-state');
  const statusRegion = document.getElementById('status-region');

  // Helpers
  function announce(message) {
    statusRegion.textContent = '';
    // Force reflow to ensure screen readers pick up repeated messages
    void statusRegion.offsetWidth;
    statusRegion.textContent = message;
  }

  function validatePageCount(value) {
    const num = Number(value);
    return Number.isInteger(num) && num > 0 ? num : null;
  }

  // Core logic
  function addBook(title, pageCount) {
    const trimmed = title.trim();
    if (!trimmed) {
      return { ok: false, error: 'Please enter a book title.' };
    }
    const pages = validatePageCount(pageCount);
    if (pages === null) {
      return { ok: false, error: 'Page count must be a positive whole number.' };
    }
    const book = {
      id: nextId++,
      title: trimmed,
      pageCount: pages,
      pagesRead: 0,
      finished: false
    };
    books.push(book);
    return { ok: true, book };
  }

  function logPages(bookId, amount) {
    const book = books.find(b => b.id === bookId);
    if (!book) return { ok: false, error: 'Book not found.' };
    if (book.finished) return { ok: false, error: 'This book is already finished.' };
    const num = Number(amount);
    if (!Number.isInteger(num) || num <= 0) {
      return { ok: false, error: 'Pages read must be a positive whole number.' };
    }
    const remaining = book.pageCount - book.pagesRead;
    const toAdd = Math.min(num, remaining);
    book.pagesRead += toAdd;
    if (book.pagesRead >= book.pageCount) {
      book.finished = true;
    }
    return { ok: true, book, added: toAdd };
  }

  // Rendering
  function createBookCard(book) {
    const li = document.createElement('li');
    li.className = 'book-card' + (book.finished ? ' finished' : '');
    li.dataset.id = book.id;

    const header = document.createElement('div');
    header.className = 'book-header';

    const titleEl = document.createElement('span');
    titleEl.className = 'book-title';
    titleEl.textContent = book.title;

    header.appendChild(titleEl);

    if (book.finished) {
      const badge = document.createElement('span');
      badge.className = 'badge';
      badge.textContent = 'Finished';
      header.appendChild(badge);
    }

    li.appendChild(header);

    const percent = Math.min(100, Math.round((book.pagesRead / book.pageCount) * 100));

    const progressContainer = document.createElement('div');
    progressContainer.className = 'progress-container';

    const progressBar = document.createElement('div');
    progressBar.className = 'progress-bar';
    progressBar.setAttribute('role', 'progressbar');
    progressBar.setAttribute('aria-valuemin', '0');
    progressBar.setAttribute('aria-valuemax', '100');
    progressBar.setAttribute('aria-valuenow', String(percent));
    progressBar.setAttribute('aria-label', 'Reading progress for ' + book.title);

    const fill = document.createElement('div');
    fill.className = 'progress-fill' + (book.finished ? ' finished' : '');
    fill.style.width = percent + '%';
    progressBar.appendChild(fill);
    progressContainer.appendChild(progressBar);

    const progressText = document.createElement('div');
    progressText.className = 'progress-text';
    const pagesInfo = document.createElement('span');
    pagesInfo.textContent = book.pagesRead + ' / ' + book.pageCount + ' pages';
    const percentInfo = document.createElement('span');
    percentInfo.textContent = percent + '%';
    progressText.appendChild(pagesInfo);
    progressText.appendChild(percentInfo);
    progressContainer.appendChild(progressText);

    li.appendChild(progressContainer);

    if (!book.finished) {
      const logForm = document.createElement('form');
      logForm.className = 'log-form';
      logForm.setAttribute('novalidate', '');

      const field = document.createElement('div');
      field.className = 'field';

      const label = document.createElement('label');
      label.htmlFor = 'log-pages-' + book.id;
      label.textContent = 'Pages read';

      const input = document.createElement('input');
      input.type = 'number';
      input.id = 'log-pages-' + book.id;
      input.min = '1';
      input.step = '1';
      input.placeholder = 'e.g., 10';
      input.required = true;

      field.appendChild(label);
      field.appendChild(input);

      const btn = document.createElement('button');
      btn.type = 'submit';
      btn.className = 'btn primary small';
      btn.textContent = 'Log pages';

      logForm.appendChild(field);
      logForm.appendChild(btn);

      logForm.addEventListener('submit', function (e) {
        e.preventDefault();
        const val = input.value;
        const result = logPages(book.id, val);
        if (!result.ok) {
          announce(result.error);
          input.focus();
          return;
        }
        input.value = '';
        render();
        if (result.book.finished) {
          announce('Congratulations! You finished "' + result.book.title + '".');
        } else {
          announce('Logged ' + result.added + ' page' + (result.added === 1 ? '' : 's') + ' for "' + result.book.title + '".');
        }
      });

      li.appendChild(logForm);
    }

    return li;
  }

  function render() {
    bookList.innerHTML = '';
    if (books.length === 0) {
      emptyState.style.display = '';
    } else {
      emptyState.style.display = 'none';
      books.forEach(function (book) {
        bookList.appendChild(createBookCard(book));
      });
    }
  }

  // Event listeners
  addForm.addEventListener('submit', function (e) {
    e.preventDefault();
    addError.textContent = '';
    const title = titleInput.value;
    const pages = pagesInput.value;
    const result = addBook(title, pages);
    if (!result.ok) {
      addError.textContent = result.error;
      (title.trim() ? pagesInput : titleInput).focus();
      return;
    }
    titleInput.value = '';
    pagesInput.value = '';
    titleInput.focus();
    render();
    announce('Added "' + result.book.title + '" with ' + result.book.pageCount + ' pages.');
  });

  // Initial render
  render();
})();
